from pathlib import Path
import sys

p = Path(sys.argv[1])
s = p.read_text(encoding='utf-8')
if 'APIRA_SECURITY_GUIDES_V1' in s:
    raise SystemExit(0)

css = r'''
        /* APIRA_SECURITY_GUIDES_V1 */
        .security-recommendation{cursor:pointer;border-radius:12px;transition:.18s ease}.security-recommendation:hover{background:rgba(139,92,246,.055)}
        .security-recommendation-main{min-width:0}.security-recommendation-head{display:flex;align-items:center;justify-content:space-between;gap:9px}.security-guide-open{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--border);background:rgba(255,255,255,.035);color:var(--muted);border-radius:9px;padding:6px 8px;font:inherit;font-size:7px;font-weight:800;cursor:pointer}.security-guide-open i{width:13px}
        .security-guide-modal{width:min(720px,calc(100vw - 24px));max-height:86vh;overflow:hidden;padding:0}.security-guide-modal .modal-header{padding:18px 20px;margin:0}.security-guide-body{overflow:auto;max-height:calc(86vh - 78px);padding:0 20px 22px}.security-guide-intro{color:var(--muted);font-size:9px;line-height:1.9;margin:0 0 15px}
        .security-guide-warning{display:flex;gap:10px;align-items:flex-start;border:1px solid rgba(245,158,11,.18);background:rgba(245,158,11,.055);border-radius:13px;padding:12px 13px;margin-bottom:16px}.security-guide-warning i{width:17px;color:#fbbf24}.security-guide-warning strong{display:block;font-size:8px;margin-bottom:4px}.security-guide-warning p,.security-guide-step p,.security-guide-check p{color:var(--muted);font-size:8px;line-height:1.75}
        .security-guide-step{display:grid;grid-template-columns:28px minmax(0,1fr);gap:10px;margin:16px 0}.security-guide-step-num{width:28px;height:28px;display:grid;place-items:center;border-radius:9px;background:rgba(139,92,246,.11);color:var(--purple-light);font-size:8px;font-weight:900}.security-guide-step h3{font-size:10px;margin:3px 0 5px}.security-code{position:relative;margin-top:9px;border:1px solid rgba(148,163,184,.17);border-radius:12px;background:#090d18;overflow:hidden;direction:ltr;text-align:left}.security-code pre{margin:0;padding:13px 48px 13px 13px;overflow:auto;color:#d9e2f2;font:7.5px/1.75 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;white-space:pre}.security-copy-btn{position:absolute;top:8px;right:8px;display:grid;place-items:center;width:31px;height:29px;border:1px solid rgba(148,163,184,.18);background:#151b2a;color:#aab4c8;border-radius:8px;cursor:pointer}.security-copy-btn i{width:13px}.security-guide-check{margin-top:18px;border-top:1px solid var(--border);padding-top:16px}.security-guide-check h3{font-size:9px;margin-bottom:7px}
        @media(max-width:640px){.security-guide-modal{width:calc(100vw - 16px);max-height:90vh}.security-guide-body{max-height:calc(90vh - 72px);padding:0 15px 18px}}
'''

modal = r'''
    <!-- APIRA_SECURITY_GUIDE_MODAL -->
    <div class="modal-backdrop" id="securityGuideModal"><div class="modal security-guide-modal" role="dialog" aria-modal="true" aria-labelledby="securityGuideTitle"><div class="modal-header"><div><div class="eyebrow" id="securityGuideEyebrow">Security guide</div><h2 id="securityGuideTitle">Security guide</h2></div><button class="icon-btn" id="closeSecurityGuideModal" type="button"><i data-lucide="x"></i></button></div><div class="security-guide-body" id="securityGuideBody"></div></div></div>
'''

js = r'''
            const APIRA_SECURITY_GUIDES={
              firewall:{m:/firewall/i,en:['Enable a host firewall','Allow SSH first, then decide which other ports your projects need.','Do not enable UFW before you inventory required ports.',[['Check SSH','Confirm the current SSH listener.','sudo ss -lntp | grep sshd'],['Allow SSH first','This does not change the SSH port.','sudo ufw allow {SSH_PORT}/tcp'],['Review listeners','See what is public before adding rules.','sudo ss -tulpn'],['Allow web ports if needed','Examples only; open ports your services actually need.','sudo ufw allow 80/tcp\nsudo ufw allow 443/tcp\n# Only if the panel stays directly public:\nsudo ufw allow 789/tcp'],['Enable after review','Keep the current SSH session open while testing.','sudo ufw status numbered\nsudo ufw enable\nsudo ufw status verbose']],'Open a second SSH connection before closing the current one.'],fa:['فعال‌کردن فایروال سرور','اول پورت SSH فعلی را مجاز کن، بعد مشخص کن کدام پورت‌های عمومی واقعاً لازم‌اند.','قبل از لیست‌کردن پورت‌های لازم UFW را فعال نکن و اتصال SSH فعلی را باز نگه دار.',[['SSH فعلی را بررسی کن','پورت واقعی SSH را ببین.','sudo ss -lntp | grep sshd'],['اول SSH را مجاز کن','این دستور پورت SSH را عوض نمی‌کند.','sudo ufw allow {SSH_PORT}/tcp'],['پورت‌ها را بررسی کن','قبل از ساخت قوانین بیشتر سرویس‌های در حال گوش‌دادن را ببین.','sudo ss -tulpn'],['پورت‌های وب را در صورت نیاز باز کن','این‌ها فقط مثال‌اند.','sudo ufw allow 80/tcp\nsudo ufw allow 443/tcp\n# فقط اگر پنل مستقیم عمومی بماند:\nsudo ufw allow 789/tcp'],['بعد از بررسی فعال کن','قوانین را ببین و بعد فایروال را روشن کن.','sudo ufw status numbered\nsudo ufw enable\nsudo ufw status verbose']],'قبل از بستن اتصال فعلی با یک SSH جدید وارد شو.']},
              root:{m:/root login|PermitRootLogin/i,en:['Restrict direct root login','Limit direct root access or allow it only with SSH keys.','Do not fully disable root until another sudo account is tested.',[['Back up config','Keep a rollback copy.','sudo cp /etc/ssh/sshd_config /etc/ssh/sshd_config.apira-backup'],['Check effective value','See what sshd uses.','sudo sshd -T | grep -i permitrootlogin'],['Use a safer policy','Block root passwords while keeping key login.','sudoedit /etc/ssh/sshd_config\nPermitRootLogin prohibit-password'],['Validate and reload','Never reload an invalid config.','sudo sshd -t && sudo systemctl reload ssh']],'Test a second SSH session before closing the first.'],fa:['محدودکردن ورود مستقیم root','ورود مستقیم root را محدود کن یا فقط با SSH Key اجازه بده.','تا وقتی یک کاربر دیگر با sudo را تست نکرده‌ای ورود root را کامل نبند.',[['بکاپ بگیر','یک نسخه برای برگشت نگه دار.','sudo cp /etc/ssh/sshd_config /etc/ssh/sshd_config.apira-backup'],['مقدار واقعی را ببین','تنظیم فعال sshd را بررسی کن.','sudo sshd -T | grep -i permitrootlogin'],['حالت امن‌تر را تنظیم کن','ورود root با رمز را ببند و Key را نگه دار.','sudoedit /etc/ssh/sshd_config\nPermitRootLogin prohibit-password'],['بررسی و Reload کن','کانفیگ خراب را Reload نکن.','sudo sshd -t && sudo systemctl reload ssh']],'با یک نشست SSH دوم تست کن.']},
              password:{m:/password authentication|SSH keys/i,en:['Disable SSH password login','SSH keys are safer against brute-force.','Confirm key login first or you may lock yourself out.',[['Check keys','Verify an authorized key exists.','ls -la ~/.ssh/authorized_keys\nssh-keygen -lf ~/.ssh/authorized_keys'],['Test key login','Use a second terminal on your device.','ssh -i ~/.ssh/YOUR_KEY root@YOUR_SERVER_IP'],['Disable passwords','Only after the key test succeeds.','sudoedit /etc/ssh/sshd_config\nPasswordAuthentication no'],['Validate and reload','Validate first.','sudo sshd -t && sudo systemctl reload ssh']],'Keep the old session open until a fresh key login works.'],fa:['غیرفعال‌کردن ورود SSH با رمز','SSH Key در برابر Brute-force امن‌تر است.','قبل از خاموش‌کردن Password حتماً ورود با Key را تست کن.',[['کلیدها را بررسی کن','مطمئن شو authorized_keys وجود دارد.','ls -la ~/.ssh/authorized_keys\nssh-keygen -lf ~/.ssh/authorized_keys'],['ورود دوم تست کن','از دستگاه خودت با Private Key وصل شو.','ssh -i ~/.ssh/YOUR_KEY root@YOUR_SERVER_IP'],['ورود با رمز را خاموش کن','فقط بعد از موفقیت تست Key.','sudoedit /etc/ssh/sshd_config\nPasswordAuthentication no'],['بررسی و Reload کن','اول Syntax را تست کن.','sudo sshd -t && sudo systemctl reload ssh']],'اتصال قبلی را تا موفقیت ورود جدید باز نگه دار.']},
              updates:{m:/security updates|package update/i,en:['Install security updates safely','Review changes before installing updates.','Do not blindly reboot or accept unexpected removals.',[['Refresh package lists','Get current metadata.','sudo apt update'],['Review updates','See pending packages.','apt list --upgradable'],['Simulate first','Spot unexpected changes.','sudo apt-get -s upgrade'],['Apply updates','Proceed when the preview looks safe.','sudo apt upgrade']],'Check apt list --upgradable and systemctl --failed afterwards.'],fa:['نصب امن آپدیت‌های امنیتی','قبل از نصب تغییرات را ببین.','روی سرور شلوغ کورکورانه Reboot یا حذف پکیج را تأیید نکن.',[['فهرست را تازه کن','آخرین اطلاعات مخزن‌ها را بگیر.','sudo apt update'],['آپدیت‌ها را ببین','قبل از نصب بررسی کن.','apt list --upgradable'],['اول شبیه‌سازی کن','تغییر غیرمنتظره را پیدا کن.','sudo apt-get -s upgrade'],['بعد نصب کن','اگر پیش‌نمایش امن بود ادامه بده.','sudo apt upgrade']],'بعدش apt list --upgradable و systemctl --failed را بررسی کن.']},
              failed:{m:/failed SSH logins|failed login/i,en:['Review failed SSH logins','Failed attempts are common; unknown successful logins matter more.','A failed attempt does not mean compromise.',[['Failed attempts','Review the last 24 hours.','sudo journalctl -u ssh --since "24 hours ago" --no-pager | grep -Ei "Failed password|Invalid user" | tail -100'],['Successful logins','Compare source IPs with your own.','sudo journalctl -u ssh --since "24 hours ago" --no-pager | grep -Ei "Accepted (password|publickey)" | tail -100'],['Login history','Inspect recent sessions.','last -ai | head -50'],['Optional Fail2ban','Enable temporary automated bans.','sudo apt update\nsudo apt install fail2ban\nsudo systemctl enable --now fail2ban\nsudo fail2ban-client status sshd']],'If a successful login comes from an unknown IP, rotate credentials and investigate.'],fa:['بررسی ورودهای ناموفق SSH','تلاش ناموفق طبیعی است؛ ورود موفق از IP ناشناس مهم‌تر است.','تلاش ناموفق به معنی هک‌شدن نیست.',[['تلاش‌های ناموفق','۲۴ ساعت اخیر را ببین.','sudo journalctl -u ssh --since "24 hours ago" --no-pager | grep -Ei "Failed password|Invalid user" | tail -100'],['ورودهای موفق','IPها را با اتصال‌های خودت مقایسه کن.','sudo journalctl -u ssh --since "24 hours ago" --no-pager | grep -Ei "Accepted (password|publickey)" | tail -100'],['تاریخچه ورود','نشست‌های اخیر را ببین.','last -ai | head -50'],['Fail2ban اختیاری','Ban موقت خودکار فعال کن.','sudo apt update\nsudo apt install fail2ban\nsudo systemctl enable --now fail2ban\nsudo fail2ban-client status sshd']],'اگر ورود موفق از IP ناشناس دیدی رمزها و Keyها را عوض کن و سرور را بررسی کن.']}
            };
            const securityGuideKey=i=>{const h=`${i?.title||''} ${i?.message||''}`;return Object.keys(APIRA_SECURITY_GUIDES).find(k=>APIRA_SECURITY_GUIDES[k].m.test(h))||null};
            const securityGuideLang=()=>localStorage.getItem('apira_language')==='fa'?'fa':'en';
            const securityGuideCode=v=>String(v||'').replaceAll('{SSH_PORT}',String(number(first(state.security||{},['ssh','port'],22))||22));
            function securityGuideCopy(btn,v){v=securityGuideCode(v);const done=()=>{btn.innerHTML='<i data-lucide="check"></i>';refreshIcons();setTimeout(()=>{btn.innerHTML='<i data-lucide="copy"></i>';refreshIcons()},1000)},legacy=()=>{const a=document.createElement('textarea');a.value=v;a.style.cssText='position:fixed;opacity:0';document.body.appendChild(a);a.select();try{document.execCommand('copy');done()}finally{a.remove()}};if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(v).then(done).catch(legacy);else legacy()}
            let activeSecurityGuide=null;
            function openSecurityGuide(k){const e=APIRA_SECURITY_GUIDES[k];if(!e)return;activeSecurityGuide=k;const fa=securityGuideLang()==='fa',g=e[fa?'fa':'en'],[title,intro,warn,steps,check]=g;text('securityGuideEyebrow',fa?'راهنمای امنیت':'Security guide');text('securityGuideTitle',title);const b=$('securityGuideBody');b.innerHTML=`<p class="security-guide-intro">${escapeHtml(intro)}</p><div class="security-guide-warning"><i data-lucide="triangle-alert"></i><div><strong>${fa?'قبل از شروع':'Before you start'}</strong><p>${escapeHtml(warn)}</p></div></div>${steps.map((x,i)=>`<div class="security-guide-step"><div class="security-guide-step-num">${i+1}</div><div><h3>${escapeHtml(x[0])}</h3><p>${escapeHtml(x[1])}</p><div class="security-code"><pre>${escapeHtml(securityGuideCode(x[2]))}</pre><button class="security-copy-btn" type="button" data-code="${escapeHtml(x[2])}"><i data-lucide="copy"></i></button></div></div></div>`).join('')}<div class="security-guide-check"><h3>${fa?'چطور مطمئن شوم؟':'How do I verify it?'}</h3><p>${escapeHtml(check)}</p></div>`;b.querySelectorAll('[data-code]').forEach(x=>x.onclick=ev=>{ev.stopPropagation();securityGuideCopy(x,x.dataset.code)});$('securityGuideModal').classList.add('show');document.body.style.overflow='hidden';refreshIcons()}
            function closeSecurityGuide(){$('securityGuideModal')?.classList.remove('show');document.body.style.overflow='';activeSecurityGuide=null}
'''

css_marker = '        .security-recommendation p { margin-top: 5px; color: var(--muted); font-size: 8px; line-height: 1.65; }\n'
s = s.replace(css_marker, css_marker + css, 1)
s = s.replace('    <!-- SSH port modal -->\n', modal + '\n    <!-- SSH port modal -->\n', 1)
s = s.replace('            function renderSecurity() {\n', js + '\n            function renderSecurity() {\n', 1)
old = '''                        return `<article class="security-recommendation ${severity}">\n                            <div class="security-recommendation-icon"><i data-lucide="${icons[severity]}"></i></div>\n                            <div><strong>${escapeHtml(item.title || "Security recommendation")}</strong><p>${escapeHtml(item.message || "")}</p></div>\n                        </article>`;'''
new = '''                        const guideKey = securityGuideKey(item);\n                        const guideLabel = securityGuideLang() === "fa" ? "راهنما" : "Guide";\n                        return `<article class="security-recommendation ${severity}" ${guideKey ? `data-security-guide="${guideKey}" tabindex="0" role="button"` : ""}>\n                            <div class="security-recommendation-icon"><i data-lucide="${icons[severity]}"></i></div>\n                            <div class="security-recommendation-main"><div class="security-recommendation-head"><strong>${escapeHtml(item.title || "Security recommendation")}</strong>${guideKey ? `<button class="security-guide-open" type="button" data-security-guide-open="${guideKey}"><i data-lucide="book-open-text"></i>${guideLabel}</button>` : ""}</div><p>${escapeHtml(item.message || "")}</p></div>\n                        </article>`;'''
if old not in s:
    raise SystemExit('recommendation renderer marker not found')
s = s.replace(old, new, 1)
handlers = '''            $("securityRecommendations")?.addEventListener("click",event=>{const t=event.target.closest("[data-security-guide-open],[data-security-guide]");const k=t?.dataset.securityGuideOpen||t?.dataset.securityGuide;if(k)openSecurityGuide(k)});\n            $("securityRecommendations")?.addEventListener("keydown",event=>{if((event.key==="Enter"||event.key===" ")&&event.target.matches("[data-security-guide]")){event.preventDefault();openSecurityGuide(event.target.dataset.securityGuide)}});\n            $("closeSecurityGuideModal")?.addEventListener("click",closeSecurityGuide);\n            $("securityGuideModal")?.addEventListener("click",event=>{if(event.target===$("securityGuideModal"))closeSecurityGuide()});\n            window.addEventListener("apira-language-changed",()=>{if(activeSecurityGuide)openSecurityGuide(activeSecurityGuide)});\n\n'''
s = s.replace('            async function loadSecurity({ silent = false } = {}) {\n', handlers + '            async function loadSecurity({ silent = false } = {}) {\n', 1)
p.write_text(s, encoding='utf-8')
